// 24-S7 acceptance: the D2 rule. Another account's committed edit
// supersedes my latest burst when it changes a cell I wrote to a different
// value, while my cursor has stayed in the entry holding it or within 3 s of
// the burst completing. The note describes the entry before and after when
// it is still the same word, and the cells otherwise. Hints follow the same
// rule (D8). Pure. Do not edit this file to match an implementation.
import { describe, expect, it } from 'vitest';
import { createGrid, withLetter, type Coord, type Grid } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import type { PuzzleContent } from './apply';
import {
  CONFLICT_WINDOW_MS, gridConflict, hintConflict, isRecent, leftEntry, recordBurst, recordHint, type IncomingOp,
} from './conflict';
import type { CellWrite, Operation } from './operation';

const jay = { userId: 'jay', username: 'Jay' };
const adam = { userId: 'adam', username: 'Adam' };
const SELF = 'adam';

function letters(grid: Grid, entries: Array<[number, number, string | null]>): Grid {
  return entries.reduce((next, [col, row, letter]) => withLetter(next, { col, row }, letter), grid);
}
const content = (grid: Grid, phase: 'grid' | 'hints' = 'grid', hints: Record<string, string> = {}): PuzzleContent =>
  ({ grid: serializeGrid(grid), hints, title: 'T', phase });
const down = (col: number, from: number, word: string): Array<[number, number, string | null]> =>
  [...word].map((letter, index) => [col, from + index, letter === '.' ? null : letter]);
const writes = (entries: Array<[number, number, string | null]>): CellWrite[] =>
  entries.map(([col, row, value]) => ({ col, row, value }));
let n = 0;
const cellsOp = (entries: Array<[number, number, string | null]>): Operation =>
  ({ opId: `op-${n++}`, puzzleId: 'p', clientId: 'other', epoch: 0, baseVersion: 1, kind: 'cells', writes: writes(entries) });
const incoming = (op: Operation, author: typeof jay | null, own = false): IncomingOp => ({ op, author, own });
const column = (col: number, from: number, to: number): Coord[] =>
  Array.from({ length: to - from + 1 }, (_, index) => ({ col, row: from + index }));

// A 7×7 in Build: ABRAHAM in 1-Across; its M starts 2-Down.
const abraham = letters(createGrid({ cols: 7, rows: 7 }), [...'ABRAHAM'].map((letter, col) => [col, 0, letter] as [number, number, string]));
const MINE: Array<[number, number, string]> = [[6, 1, 'A'], [6, 2, 'S'], [6, 3, 'K'], [6, 4, 'S']];
const masks = letters(abraham, MINE);
const T = 1_000_000;
const recent = () => recordBurst(content(masks), writes(MINE), 'down', T);
const LAST = { col: 6, row: 4 };

function conflictAfter(
  after: Grid, ops: IncomingOp[], options: { cursor?: Coord; now?: number; burst?: ReturnType<typeof recent> } = {},
) {
  return gridConflict({
    recent: options.burst ?? recent(), before: content(masks), after: content(after), ops, self: SELF,
    cursor: options.cursor ?? LAST, now: options.now ?? T + 10_000,
  });
}

describe('24-S7-4 the D2 rule for the grid', () => {
  it('MASKS, then Jay’s MAGIC: 2-Down’s cells outlined and the note', () => {
    const magic = cellsOp([[6, 2, 'G'], [6, 3, 'I'], [6, 4, 'C']]);
    const found = conflictAfter(letters(masks, [[6, 2, 'G'], [6, 3, 'I'], [6, 4, 'C']]), [incoming(magic, jay)]);
    expect(found).toEqual({ author: jay, cells: column(6, 0, 4), message: 'Jay changed 2-Down from MASKS to MAGIC.' });
  });

  it('Jay typing only MAG gives MAGKS', () => {
    const mag = cellsOp([[6, 2, 'G']]);
    expect(conflictAfter(letters(masks, [[6, 2, 'G']]), [incoming(mag, jay)])?.message)
      .toBe('Jay changed 2-Down from MASKS to MAGKS.');
  });

  it('recent while the cursor stays in the entry, however long; after leaving, for 3 s from completion', () => {
    const op = cellsOp([[6, 2, 'G']]);
    const after = letters(masks, [[6, 2, 'G']]);
    expect(conflictAfter(after, [incoming(op, jay)], { now: T + 60_000 })).not.toBeNull();
    const away = { col: 2, row: 3 };
    const left = leftEntry(recent(), away);
    expect(isRecent(left, away, T + CONFLICT_WINDOW_MS - 1)).toBe(true);
    expect(conflictAfter(after, [incoming(op, jay)], { burst: left, cursor: away, now: T + CONFLICT_WINDOW_MS - 1 })).not.toBeNull();
    expect(conflictAfter(after, [incoming(op, jay)], { burst: left, cursor: away, now: T + CONFLICT_WINDOW_MS + 1 })).toBeNull();
    // Coming back doesn't make it recent again.
    expect(conflictAfter(after, [incoming(op, jay)], { burst: left, cursor: LAST, now: T + CONFLICT_WINDOW_MS + 1 })).toBeNull();
    expect(leftEntry(recent(), { col: 6, row: 1 })).toEqual(recent());
  });

  it('nothing for the same value, an unrelated cell, my own account, this tab, or a later write of mine', () => {
    const same = cellsOp([[6, 2, 'S']]);
    expect(conflictAfter(masks, [incoming(same, jay)])).toBeNull();
    const elsewhere = cellsOp([[2, 3, 'Q']]);
    expect(conflictAfter(letters(masks, [[2, 3, 'Q']]), [incoming(elsewhere, jay)])).toBeNull();
    const g = cellsOp([[6, 2, 'G']]);
    const after = letters(masks, [[6, 2, 'G']]);
    expect(conflictAfter(after, [incoming(g, adam)])).toBeNull();
    expect(conflictAfter(after, [incoming(g, jay, true)])).toBeNull();
    const mineLater = cellsOp([[6, 2, 'X']]);
    expect(conflictAfter(letters(masks, [[6, 2, 'X']]), [incoming(g, jay), incoming(mineLater, adam)])).toBeNull();
    expect(gridConflict({
      recent: null, before: content(masks), after: content(after), ops: [incoming(g, jay)], self: SELF, cursor: LAST, now: T,
    })).toBeNull();
  });

  it('a cell shown other than mine before the batch is not mine to lose', () => {
    const g = cellsOp([[6, 2, 'G']]);
    const before = letters(masks, [[6, 2, 'Z']]);
    expect(gridConflict({
      recent: recent(), before: content(before), after: content(letters(masks, [[6, 2, 'G']])),
      ops: [incoming(g, jay)], self: SELF, cursor: LAST, now: T + 1000,
    })).toBeNull();
  });

  it('when the entry’s shape changes, the note and the outline are the cells', () => {
    const cleared = cellsOp([[6, 3, null], [6, 4, null]]);
    const found = conflictAfter(letters(masks, [[6, 3, null], [6, 4, null]]), [incoming(cleared, jay)]);
    expect(found).toEqual({ author: jay, cells: [{ col: 6, row: 3 }, { col: 6, row: 4 }], message: 'Jay changed 2 letters you just typed in 2-Down.' });
    const one = cellsOp([[6, 4, null]]);
    expect(conflictAfter(letters(masks, [[6, 4, null]]), [incoming(one, null)])?.message)
      .toBe('A builder changed a letter you just typed in 2-Down.');
  });
});

describe('24-S7-4 the D2 rule for hints', () => {
  let full = createGrid({ cols: 3, rows: 3 });
  for (let row = 0; row < 3; row++) for (let col = 0; col < 3; col++) full = withLetter(full, { col, row }, 'A');
  const before = content(full, 'hints', { '1-across': 'Mine' });
  const after = content(full, 'hints', { '1-across': 'Theirs' });
  const hintOp = (key: string, text: string): Operation =>
    ({ opId: `h-${n++}`, puzzleId: 'p', clientId: 'other', epoch: 0, baseVersion: 1, kind: 'hint', key, text });
  const mine = () => recordHint(before, '1-across', 'Mine', T);
  const inEntry = { col: 1, row: 0 };
  const check = (options: { ops?: IncomingOp[]; cursor?: Coord; now?: number; burst?: ReturnType<typeof mine>; was?: PuzzleContent }) =>
    hintConflict({
      recent: options.burst ?? mine(), before: options.was ?? before, after, ops: options.ops ?? [incoming(hintOp('1-across', 'Theirs'), jay)],
      self: SELF, cursor: options.cursor ?? inEntry, now: options.now ?? T + 10_000,
    });

  it('another builder replacing my recent hint highlights it, with a note', () => {
    expect(check({})).toEqual({ key: '1-across', author: jay, message: 'Jay changed your hint for 1-Across.' });
  });

  it('not after leaving it for 3 s, nor for another key, my own account, or text already replaced', () => {
    const away = { col: 0, row: 2 };
    expect(check({ burst: leftEntry(mine(), away), cursor: away, now: T + 1000 })).not.toBeNull();
    expect(check({ burst: leftEntry(mine(), away), cursor: away, now: T + CONFLICT_WINDOW_MS + 1 })).toBeNull();
    expect(check({ ops: [incoming(hintOp('1-down', 'Theirs'), jay)] })).toBeNull();
    expect(check({ ops: [incoming(hintOp('1-across', 'Theirs'), adam)] })).toBeNull();
    expect(check({ was: content(full, 'hints', { '1-across': 'Earlier' }) })).toBeNull();
  });
});
